create table if not exists jlc.activation_gates (gate_code text primary key,corridor_code text not null references jlc.corridors(corridor_code) on delete cascade,subject_reference text not null,gate_type text not null check(gate_type in ('EVIDENCE','COUNTERPARTY','SPATIAL','REGULATORY','COMMERCIAL','CAPITAL','OPERATIONS')),required_evidence text not null,gate_state text not null default 'OPEN' check(gate_state in ('OPEN','EVIDENCE_IDENTIFIED','PENDING_VERIFICATION','SATISFIED','BLOCKED','WAIVED','ARCHIVED')),source_reference text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table jlc.activation_gates enable row level security; grant select,insert,update,delete on jlc.activation_gates to service_role; revoke all on jlc.activation_gates from anon,authenticated; create policy service_role_all on jlc.activation_gates for all to service_role using(true) with check(true);
insert into jlc.evidence_links(evidence_code,subject_type,subject_reference,title,source_system,source_uri,evidence_class,verification_state) values ('JLC-EV-004','PROGRAM','JLC-PROG-JRC-MULTIMODAL','Jamaica Railway Corporation National Corridor Activation Platform','GOOGLE_DRIVE','https://docs.google.com/document/d/1IBtzcuDcmVTT92sLEqmKsVZ2Y7hSChCijgWQ9LHiW4c/edit','INTERNAL_DOCUMENT','EVIDENCE_SUPPORTED') on conflict(evidence_code) do nothing;
insert into jlc.activation_gates(gate_code,corridor_code,subject_reference,gate_type,required_evidence,gate_state,source_reference,notes) values ('JLC-GATE-JRC-001','JLC-001','JLC-NODE-JRC-MULTIMODAL','EVIDENCE','Authoritative executed agreement, government/JRC resolution, concession, operating authority, or equivalent external evidence establishing the proposed rail activation relationship.','EVIDENCE_IDENTIFIED','DRIVE:JRC-NATIONAL-CORRIDOR-ACTIVATION','Drive evidence supports the proposed freight-rail/multimodal architecture, including Kingston Port, logistics parks, inland freight terminals, cargo transfer hubs, bonded logistics and smart freight systems. The document itself is an Executive Alignment Draft and does not independently establish execution authority.'),('JLC-GATE-CAYMANAS-001','JLC-001','JLC-NODE-CAYMANAS-SEZ','COUNTERPARTY','JSEZA/PAJ participation, occupancy, development, lease, procurement award, or other authoritative project-specific evidence.','OPEN','JIS:CAYMANAS-SEZ','Keep Caymanas in PLANNING until project-specific participation is evidenced.'),('JLC-GATE-TINSON-001','JLC-001','JLC-NODE-TINSON-PEN','COUNTERPARTY','PAJ/government land, lease, operating, procurement, partnership, or other project-specific participation evidence.','OPEN','JIS:NEAR-PORT-LANDS','Government development evidence validates the opportunity but not SourceEnergy/RGL participation.'),('JLC-GATE-RAIL-ASSETS-001','JLC-001','JLC-PROG-JRC-MULTIMODAL','SPATIAL','Canonical rail network and terminal records backed by authoritative route, asset, station/terminal, geospatial, or operator evidence.','OPEN','DRIVE:JRC-NATIONAL-CORRIDOR-ACTIVATION','No Jamaica rail_networks or rail_terminals currently exist in the canonical RGL tables; do not fabricate them.'),('JLC-GATE-DRONE-001','JLC-001','JLC-001','REGULATORY','Canonical Jamaica drone hub/zone records plus applicable aviation/regulatory authority evidence and operating constraints.','OPEN',null,'No Jamaica drone hubs were found in the canonical RGL registry; activation remains gated.') on conflict(gate_code) do nothing;
update jlc.programs set lifecycle_state='DILIGENCE',updated_at=now(),evidence_reference='DRIVE:JRC-NATIONAL-CORRIDOR-ACTIVATION' where program_code='JLC-PROG-JRC-MULTIMODAL' and lifecycle_state='PLANNING';
